import{z as r,x as t,o as e,c as s,q as A,j as n,D as a,d as i,s as o,S as l}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"因果应用收束","description":"","frontmatter":{"title":"因果应用收束","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ca-map.md","filePath":"econ/ca-map.md","lastUpdated":1791063341000}'),c={name:"econ/ca-map.md"};function d(p,E,D,h,C,m){const B=t("Mermaid");return e(),s("div",null,[E[2]||(E[2]=A('<h1 id="因果应用收束" tabindex="-1">因果应用收束 <a class="header-anchor" href="#因果应用收束" aria-label="Permalink to &quot;因果应用收束&quot;">​</a></h1><div class="epigraph"><p>换到哪个学科都一样：先问反事实从哪里来，再问读数为谁而估，最后问证据怎么搬家。</p><footer>—— 据 Card, Econometrica 2001；Abadie, Diamond and Hainmueller, JASA 2010；Finkelstein 等, QJE 2012 整理</footer></div><p><a href="/econ/ca-evidence-hierarchy">上一课</a>把散落的估计收进分级与合成的程序。本课收束全课程：把四个应用域放回工具箱各走一遍，再按读序重排六课。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收束靠回放。四个域的起点都是同一种缺口：生产函数里能力与投入纠缠（教育）、教科书预测与数据脱节（劳动）、链条「保险 → 利用 → 健康」三段各有一个混淆源（健康）、排放反事实与剂量反应双缺（环境）。每个域都用自己的制度缝隙补上变异：教育有校内随机与编班规则，劳动有法条与税表拐点，健康有抽签与年龄线，环境有阈值与供暖法线。应用的推进从来不靠新估计量，靠的是把可行缝隙找全、把威胁清单核对完。</p><p><span class="marginnote">反事实就是「同一批人如果没遇上政策会怎样」的那条看不见的线——一个县不可能同时过两种命运，所以这条线永远观察不到。应用研究的全部手艺，就是用制度留下的缝隙造对照，把这条假想的线用真实数据拼出来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按读序重排六课：</p><ul><li><a href="/econ/ca-education-causal">教育中的因果问题</a>：三个偏差与三个设计；工具回报不低于 OLS 的解释与动态互补。</li><li><a href="/econ/ca-labor-policy-evidence">劳动政策的因果证据</a>：法条的四条缝；归宿是机制的轴；元分析的中位与发表选择。</li><li><a href="/econ/ca-health-policy-evidence">健康政策的因果证据</a>：价格、资格、年龄、地理四条缝；道德风险的量与 LATE 的外推限。</li><li><a href="/econ/ca-env-policy-evidence">环境政策的因果证据</a>：阈值双刃；合成对照与许可证价格；leakage 与数据操纵。</li><li><a href="/econ/ca-evidence-hierarchy">证据的分级与综合</a>：GRADE 的威胁清单；注册、随机效应、漏斗图。</li><li>本课：把三条主线收拢。</li></ul>',9)),(e(),n(l,null,{default:a(()=>[o(B,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20DOM%5B%22%E5%BA%94%E7%94%A8%E5%9F%9F%EF%BC%9A%E5%8F%98%E5%BC%82%E4%BB%8E%E5%88%B6%E5%BA%A6%E7%BC%9D%E9%9A%99%E6%9D%A5%22%5D%0A%20%20%20%20EDU%5B%22%E6%95%99%E8%82%B2%EF%BC%9A%E9%9A%8F%E6%9C%BA%E4%B8%8E%E7%BC%96%E7%8F%AD%E8%A7%84%E5%88%99%22%5D%20--%3E%20LAB%5B%22%E5%8A%B3%E5%8A%A8%EF%BC%9A%E6%B3%95%E6%9D%A1%E4%B8%8E%E7%A8%8E%E8%A1%A8%22%5D%0A%20%20%20%20LAB%20--%3E%20HEA%5B%22%E5%81%A5%E5%BA%B7%EF%BC%9A%E6%8A%BD%E7%AD%BE%E4%B8%8E%E5%B9%B4%E9%BE%84%E7%BA%BF%22%5D%0A%20%20%20%20HEA%20--%3E%20ENV%5B%22%E7%8E%AF%E5%A2%83%EF%BC%9A%E9%98%88%E5%80%BC%E4%B8%8E%E6%B3%95%E7%BA%BF%22%5D%0A%20%20end%0A%20%20subgraph%20SYN%5B%22%E7%BB%BC%E5%90%88%EF%BC%9A%E8%AF%81%E6%8D%AE%E5%A6%82%E4%BD%95%E6%90%AC%E5%AE%B6%22%5D%0A%20%20%20%20GRA%5B%22%E5%A8%81%E8%83%81%E6%B8%85%E5%8D%95%E5%88%86%E7%BA%A7%22%5D%20--%3E%20MET%5B%22%E5%90%88%E6%88%90%E4%B8%8E%E5%BC%82%E8%B4%A8%E6%80%A7%22%5D%0A%20%20%20%20MET%20--%3E%20DEC%5B%22%E5%86%B3%E7%AD%96%E6%B3%9B%E5%87%BD%22%5D%0A%20%20end%0A%20%20DOM%20--%3E%20GRA%0A%20%20SYN%20--%3E%20CLOSE%5B%22%E4%B8%89%E9%97%AE%EF%BC%9A%E5%81%87%E8%AE%BE%E3%80%81%E7%9B%AE%E6%A0%87%E3%80%81%E6%90%AC%E8%BF%90%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[i(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<p><span class="marginnote">四域的证据密度并不均匀：健康拥有兰德与俄勒冈两代大型随机实验，环境几乎全靠阈值与法线——这不是方法偏好，是政策把不连续的缝开在哪个变量上。应用者的第一项作业永远是盘点缝隙，而不是挑选估计量。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>六课收成三条主线。<strong>变异从制度缝隙来</strong>：<a href="/econ/potential-outcomes">潜在结果</a>框架下，估计量的原料是可剥离的变异，应用域的工作是把各自制度里的缝隙找全——校内随机、州法、抽签、法线，每条缝隙写着自己的适用范围。<strong>读数为谁而估</strong>：同一设计在不同域产出不同的目标参数——教育的 LATE 落在受法律约束的边际学生，劳动的净效应带着归宿，健康的 ITT 与 TOT 分账，环境的弹性只对本地人群成立；参数口径错了，再干净的估计也是答非所问。<strong>证据是组合物</strong>：单研究的内部有效只是入场券，跨域搬运要过威胁清单、异质性与外推三关——分级与综合是应用域共用的最后一道工序。不这么做会错在哪：把课程读成四个应用题集，会漏掉真正的公共资产——缝隙盘点、口径声明与证据合成的三套程序，它们在哪个域都一样。</p>',3)),(e(),n(l,null,{default:a(()=>[o(B,{id:"mermaid-64",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E5%B7%A5%E5%BA%8F%E4%B8%80%3A%20%E6%89%BE%E7%BC%9D%E9%9A%99%20-%20%E5%88%B6%E5%BA%A6%E5%BC%80%E5%87%BA%E7%9A%84%E4%B8%8D%E8%BF%9E%E7%BB%AD%22%5D%20--%3E%20C%5B%22%E5%B7%A5%E5%BA%8F%E4%BA%8C%3A%20%E5%AE%9A%E5%8F%A3%E5%BE%84%20-%20LATE%20%2F%20ITT%20%2F%20%E5%BD%92%E5%AE%BF%20%2F%20%E6%9C%AC%E5%9C%B0%E5%BC%B9%E6%80%A7%22%5D%0A%20%20C%20--%3E%20E%5B%22%E8%AE%BE%E8%AE%A1%E5%85%91%E7%8E%B0%E5%8F%98%E5%BC%82%2C%20%E4%BC%B0%E5%87%BA%E6%95%88%E5%BA%94%22%5D%0A%20%20E%20--%3E%20A1%5B%22%E5%AE%A1%E8%AE%A1%E4%B8%80%3A%20%E5%A8%81%E8%83%81%E6%B8%85%E5%8D%95%E9%80%90%E9%A1%B9%E6%A0%B8%E5%AF%B9%22%5D%0A%20%20E%20--%3E%20A2%5B%22%E5%AE%A1%E8%AE%A1%E4%BA%8C%3A%20%E5%BC%82%E8%B4%A8%E6%80%A7%E5%BD%93%E4%BF%A1%E6%81%AF%2C%20%E4%B8%8D%E7%A1%AC%E5%B9%B3%E5%9D%87%22%5D%0A%20%20E%20--%3E%20A3%5B%22%E5%AE%A1%E8%AE%A1%E4%B8%89%3A%20%E5%A4%96%E6%8E%A8%E8%BF%87%E4%B8%89%E5%85%B3%22%5D%0A%20%20C%20-.-%3E%7C%E5%8F%A3%E5%BE%84%E9%94%99%E4%BD%8D%7C%20X%5B%22%E7%AD%94%E9%9D%9E%E6%89%80%E9%97%AE%3A%20%E6%95%B0%E5%AD%97%E5%86%8D%E5%B9%B2%E5%87%80%E4%B9%9F%E7%99%BD%E4%BC%B0%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[i(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p><span class="marginnote">口径错位是什么样：把教育工具的 LATE——被法律多留校的边际学生——当成全体青年的教育回报，就像用「被迫戒糖的病人」对糖的反应去预测所有人的甜食需求。数字再精确，答的也是另一个问题；所以收束课把「读数为谁而估」单列为一条主线。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>收束不是领域的边界：从不存在的规则外推（没征收过的碳税、没实施过的全民覆盖）是结构估计的事，<a href="/econ/se-validation">结构模型的验证</a>给过它的验证观；高维协变量与异质效应的自动化，<a href="/econ/ml-causal-econ">机器学习与因果</a>与 <a href="/econ/pm-dml-deep">Double ML 的深入</a>接着做；测量端的文本与行政数据是另一门课的输入。本课程不越界去写它们。读完本课程，默认的口径沿用政策评估课末的三问：假设写了没有、目标对准了没有、证据搬不搬得动——应用域只是把这三问，落到了各自的制度缝隙上。</p><p><span class="marginnote">三问是整套课程的出厂检查单：假设写了没有（可审计）、目标对准了没有（口径）、证据搬不搬得动（外推）。任何一份评估报告先过这三问再谈结论——省掉这道工序，后面每一步数字的精度都只是装饰。</span></p><p>本课程到此收束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四个应用域一条公理：变异从制度缝隙来，估计量只是把缝隙兑现。</li><li>读数为谁而估：LATE、ITT、归宿与本地弹性，口径先于数字。</li><li>证据是组合物：威胁清单分级、注册与合成、异质性当信息。</li><li>跨域搬运的审计口径是三问：假设、目标、搬运。</li><li>出处：Card, Econometrica 2001；Finkelstein 等, QJE 2012；Chen, Ebenstein, Greenstone and Li, PNAS 2013；Guyatt 等, GRADE 系列, BMJ 2008。</li></ul>',7))])}const u=r(c,[["render",d]]);export{T as __pageData,u as default};
